        rightArrow = "下一張投影片",
        indicator = "投影片切換至索引 {index}",
    ),
        inputOtp = ElInputOtpLocale(
        groupLabel = "一次性密碼輸入框",
        defaultLabel = "請輸入第 {index} 位 OTP 字元",
    ),
        )
    }

    val all: List<ElLocale> = listOf(
        af, arEg, ar, az, bg, bn, ca, ckb, cs, da, de, el, en, eo, es, et, eu, fa, fi, fr, gl, he, hi, hr, hu, hyAm, id, it, ja, kk, km, ko, ku, ky, lo, lt, lv, mg, mn, ms, my, nbNo, nl, no, pa, pl, ptBr, pt, ro, ru, sk, sl, sr, sv, sw, ta, te, th, tk, tr, ugCn, uk, uzUz, vi, zhCn, zhHk, zhMo, zhTw
    )

    private val registry: Map<String, ElLocale> by lazy { buildMap {
        all.forEach { locale -> put(locale.name.lowercase().replace('_', '-'), locale) }
        put("zh", zhCn)
        put("pt-br", ptBr)
        put("zh-hans", zhCn)
        put("zh-hant", zhTw)
        put("nb", nbNo)
    } }

    /** Look up a locale by BCP-47 tag, falling back from `fr-FR` to `fr`. */
    fun byName(name: String): ElLocale {
        val normalized = name.trim().lowercase().replace('_', '-')
        return registry[normalized]
            ?: registry[normalized.substringBefore('-')]
            ?: en
    }

}
